ertId();$pdo->prepare('INSERT INTO sms_events(job_id,event_type,created_at) VALUES(?,\'queued\',CURRENT_TIMESTAMP)')->execute([$jid]);$ins++;}$pdo->commit();audit('campaign_created',['id'=>$cid,'queued'=>$ins,'test_mode'=>$test]);$notice="کمپین ساخته شد: معتبر ".count($phones)."، در صف $ins، مسدود $blocked، بدون رضایت ثبت‌شده $noConsent، تکراری $dups، نامعتبر $invalid.";$page='campaigns'; }
