}
$stats=['gateways'=>(int)$pdo->query("SELECT COUNT(*) FROM gateways WHERE status='online'")->fetchColumn(),'queued'=>(int)$pdo->query("SELECT COUNT(*) FROM sms_jobs WHERE status='queued'")->fetchColumn(),'sent'=>(int)$pdo->query("SELECT COUNT(*) FROM sms_jobs WHERE status='sent'")->fetchColumn(),'failed'=>(int)$pdo->query("SELECT COUNT(*) FROM sms_jobs WHERE status='failed'")->fetchColumn(),'today'=>(int)$pdo->query('SELECT COUNT(*) FROM sms_jobs WHERE DATE(created_at)=DATE(CURRENT_TIMESTAMP)')->fetchColumn()];
$gateways=$pdo->query('SELECT * FROM gateways ORDER BY id DESC')->fetchAll();$campaigns=$pdo->query('SELECT c.*,COUNT(j.id) total,SUM(j.status=\'queued\') queued,SUM(j.status=\'sent\') sent,SUM(j.status=\'failed\') failed FROM campaigns c LEFT JOIN sms_jobs j ON j.campaign_id=c.id GROUP BY c.id ORDER BY c.id DESC LIMIT 100')->fetchAll();$contacts=$pdo->query('SELECT * FROM contacts ORDER BY id DESC LIMIT 200')->fetchAll();$settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM settings WHERE setting_key IN ('telegram_token','telegram_chat_id','test_mode','send_interval_seconds')") as $r)$settings[$r['setting_key']]=$r['setting_value'];
